// Social-Pip TikTok Pre-Publish Check
// TikTok has strict requirements and highest risk
const item = $input.first().json;

const TIKTOK_MAX_DAILY = 3;
const TIKTOK_MIN_DELAY_MS = 120 * 60 * 1000; // 2 hours (longest delay)
const TIKTOK_MAX_DESC = 2200;
const TIKTOK_MAX_HASHTAGS = 10;

const accountStats = {
  postsToday: item.postsToday || 0,
  lastPostAt: item.lastPostAt ? new Date(item.lastPostAt) : null,
  accountStatus: item.accountStatus || 'ACTIVE',
  warmupProgress: item.warmupProgress || 0,
  accountAge: item.accountAge || 0 // days
};

const errors = [];

// Very strict daily limit
if (accountStats.postsToday >= TIKTOK_MAX_DAILY) {
  errors.push(`Daily limit reached: ${accountStats.postsToday}/${TIKTOK_MAX_DAILY}`);
}

// 2 hour minimum delay
if (accountStats.lastPostAt) {
  const timeSinceLastPost = Date.now() - accountStats.lastPostAt.getTime();
  if (timeSinceLastPost < TIKTOK_MIN_DELAY_MS) {
    const waitMinutes = Math.ceil((TIKTOK_MIN_DELAY_MS - timeSinceLastPost) / 60000);
    errors.push(`Wait ${waitMinutes} minutes. TikTok requires 2h between posts.`);
  }
}

// Warmup period checks
if (accountStats.accountAge < 14 && accountStats.warmupProgress < 100) {
  // During warmup, even stricter limits
  if (accountStats.postsToday >= 1) {
    errors.push(`Account in warmup. Max 1 post/day for first 2 weeks.`);
  }
}

// TikTok-specific: MUST have video
if (!item.videoUrl && (!item.mediaUrls || item.mediaUrls.length === 0)) {
  errors.push('TikTok requires video content');
}

// Description length
if (item.content && item.content.length > TIKTOK_MAX_DESC) {
  errors.push(`Description too long: ${item.content.length}/${TIKTOK_MAX_DESC}`);
}

// Hashtag limit
if (item.hashtags && item.hashtags.length > TIKTOK_MAX_HASHTAGS) {
  errors.push(`Too many hashtags: ${item.hashtags.length}/${TIKTOK_MAX_HASHTAGS}`);
}

// Account status check
if (['BANNED', 'RESTRICTED', 'SHADOWBANNED'].includes(accountStats.accountStatus)) {
  errors.push(`Account status: ${accountStats.accountStatus}. TikTok shadowbans are common.`);
}

if (errors.length > 0) {
  return { json: { valid: false, errors, accountStats } };
}

return { json: { valid: true, post: item, accountStats } };

const result = $input.first().json;

if (result.error) {
  // TikTok-specific error handling
  let errorCode = 'UNKNOWN';
  if (result.error.includes('upload failed')) errorCode = 'E003';
  if (result.error.includes('copyright')) errorCode = 'E004';
  if (result.error.includes('restricted')) errorCode = 'E005';

  return {
    json: {
      success: false,
      error: result.error,
      errorCode,
      platform: 'tiktok'
    }
  };
}

return {
  json: {
    success: true,
    postId: result.id,
    postUrl: `https://tiktok.com/@user/video/${result.id}`,
    publishedAt: new Date().toISOString(),
    platform: 'tiktok'
  }
};

